-- INA-CBG cost weights copied from the AMATI database dump.
-- Import into the intended MySQL database while both tables are absent.
SET NAMES utf8mb4;
SET @cw_imported_at = SYSDATE();

CREATE TABLE `dt01_inacbg_cw_ranap_ms` (
  `id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `fs_kd_inacbg` varchar(255) NOT NULL,
  `fs_deskripsi` text NOT NULL,
  `fn_nilai_cw` decimal(10,2) NOT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_Date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



CREATE TABLE `dt01_inacbg_cw_rajal_ms` (
  `id` char(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `fs_kd_inacbg` varchar(255) NOT NULL,
  `fs_deskripsi` text NOT NULL,
  `fn_nilai_cw` decimal(10,2) NOT NULL,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_Date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

